+     *
+     * <p>종료할 때는 넣어 둔 일을 마치고 내려간다. 같은 이유다.
+     */
+    @Bean(destroyMethod = "shutdown")
+    TaskExecutor paramSearchProgressExecutor() {
+        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
+        executor.setCorePoolSize(1);
